var utils = window.optimizely.get('utils');
utils.waitUntil(function () {
	jquery = window.jQuery || window.optimizely.get('jquery');
  currencyInput = document.querySelectorAll('#edit-input-avg-salary');
	return (typeof window.jQuery === 'function') && (currencyInput.length > 0);
}).then(function () {
  // Change "average salary" input from USD to AU$
  // Did currency conversion then rounded to nearest 10 
  // $40,000 -> AU$50,000 and $200,000 -> AU$300,000
  jQuery('.js-form-item-input-avg-salary .field-prefix').text('AU$50,000');
  jQuery('.js-form-item-input-avg-salary .field-suffix').text('AU$300,000');
  jQuery('#edit-input-avg-salary').attr('min', '50000').attr('max', '300000').val(0); 
  jQuery('output[for="input_avg_salary"]').attr('data-field-prefix', 'AU$').text('AU$0');
  // Change output currency label for annual cost savings result
  jQuery('.js-form-item-output-annual-cost-savings .result').text('AU$');
  jQuery('.js-form-item-output-annual-cost-savings').attr('data-prefix', 'AU$'); 
  // // Change PDF download link
  var currentPdf = jQuery('#calculator-pdf-link a').attr('href');
  var newPdf = currentPdf.replace(new RegExp('\calculator-pdf', 'g'), 'aus-calculator-pdf');
  jQuery('#calculator-pdf-link a').attr('href', newPdf);
});
