// UPDATED 9/24 - Restores tinfo on first page view

function slpGetCookie(cname){
		var name = cname + "=";
		var decodedCookie = decodeURIComponent(document.cookie);
		var ca = decodedCookie.split(';');
		for(var i = 0; i <ca.length; i++) {
				var c = ca[i];
				while (c.charAt(0) == ' ') {
						c = c.substring(1);
				}
				if (c.indexOf(name) == 0) {
						return c.substring(name.length, c.length);
				}
		}
		return null;
}

function slpSetCookie(name,value,days) {
		var expires = "";
		if (days) {
				var date = new Date();
				date.setTime(date.getTime() + (days*24*60*60*1000));
				expires = "; expires=" + date.toUTCString();
		}
		document.cookie = name + "=" + (value || "")  + expires + ";path=/;domain=.smartsheet.com";
}

function cookieloop(ctr){
	doLog("Cookie Loop - start - " + ctr);
	if (ctr > 0){
			//console.log("[CDL] tinfo pull re-looped " + ctr + " times.");
	}
	if ((ctr * 1) < 20){
		var tinfocookie = slpGetCookie('tinfo');
		doLog(tinfocookie);
		if (tinfocookie == null){
				setTimeout(function(){
						cookieloop(ctr + 1);
				}, 500);
		} else {
			doLog("capture localstorage", "green");
			localStorage.setItem('_tinfo', encodeURIComponent(tinfocookie));
		}
	} else {
			console.log("[TINFO] retried too many times. Exiting.");
	}
	doLog("Cookie Loop - end - " + ctr);
}

function doLog(msg, color, prefix) {
  color = color || "black";
  if (typeof prefix === 'undefined'){
    prefix = "";
  } else {
    prefix = "[" + prefix + "] " || "";
  }
  bgc = "White";
  switch (color) {
    case "success":  color = "White";	bgc = "#00aa00";       break;
    case "info":     color = "White";	bgc = "DodgerBlue";       break;
    case "error":    color = "White";	bgc = "Red";           break;
    case "start":    color = "#666666";	bgc = "PaleGreen";       break;
    case "warning":  color = "White";	bgc = "Tomato";           break;
    case "end":      color = "White";	bgc = "MediumVioletRed"; break;
    default: color = color;
  }

  if (typeof msg == "object") {
    console.log(msg);
  } else if (typeof color == "object") {
    console.log("%c" + prefix + msg, "color: PowderBlue;font-weight:bold; background-color: RoyalBlue;");
    console.log(color);
  } else {
    console.log("%c" + prefix + msg, "color:" + color + ";font-weight:bold; background-color: " + bgc + ";");
  }
}

// SLP CAPTURING CONDITIONS
// 1. CookieConsent cookie is not set & _slp localstorage is not set
// 2. CookieConsent cookie is not set & _slp localstorage is set
//      - set _slp bit to true
//      - capture path, query params to localstorage
// 3. CookieConsent cookie is set & _slp localstorage is not set
//      - do nothing
// 4. CookieConsent cookie is set & _slp localstorage is set
//      - if CookieConsent opt in, update tinfo cookie
//      - unset all the previous localstorage values

// Cookie Consent Monitoring Function
(function(){
	// Immediately invoke this piece when first ran
	(function beforeWhile(){
		// RUN THIS FIRST
		doLog("Cookie Consent monitor init","success","Cookie Consent");

		// CHECK CONSENT STATUS
		var cc_cookie = slpGetCookie("CookieConsent");
		if (cc_cookie === null){
			noconsent = true;
		} else {
			noconsent = false;
		}

	})();

	function whileLoop(){
		doLog("Cookie Consent - Entering loop","success","Cookie Consent");
		// CONDITION = COOKIE DOES NOT EXIST
		var noconsent = true;
		
		(function noConsentCode(){
			// CHECK CONSENT STATUS
			var cc_cookie = slpGetCookie("CookieConsent");
			if (cc_cookie === null){
				noconsent = true;
			} else {
				noconsent = false;
			}

			if (noconsent){
				// RETRIGGER THE FUNCTION
				setTimeout(function(){
					noConsentCode();
				},500);
			} else {
				doLog("CookieConsent has been triggered","success","Cookie Consent");
				// CONSENT HAS BEEN GIVEN
				// COMPLETE THE FUNCTION
				// CookieConsent has happened
				if (localStorage.getItem('_tinfo') === null){
					// No tinfo captured - do nothing
				} else {
					// Normalize cookie values
					while (cc_cookie.indexOf('%2C') != -1){
							cc_cookie = cc_cookie.replace('%2C',',');
					}

					// DEFAULT PREFERENCES
					var necessary   = true;
					var preferences = false;
					var statistics  = false;
					var marketing   = false;

					// SPLIT COOKIE VALUES
					var cookiearray = cc_cookie.split(",");

					// SEE WHAT THE USER SELECTED
					cookiearray.forEach(function(item){
							var itm = item.split(":");
							switch (itm[0]){
									case "preferences":
											if (itm[1] == "true"){
													preferences = true;
											}
									break;
									case "statistics":
											if (itm[1] == "true"){
													statistics = true;
											}
									break;
									case "marketing":
											if (itm[1] == "true"){
													marketing = true;
											}
									break;
							}
					});

					// ARE ANY ADDITIONAL VALUES SELECTED AS TRUE?
					if (preferences || statistics || marketing){
						// THEY OPTED IN - CAPTURING TINFO
						doLog("CookieConsent granted - rebuilding tinfo cookie","success","Cookie Consent");

						var tinfo = localStorage.getItem('_tinfo');
						slpSetCookie("tinfo", tinfo,30);
					} else {
						doLog("CookieConsent not granted","warning","Cookie Consent");
					}
					doLog("CookieConsent clearing localStorage","success","Cookie Consent");
					localStorage.removeItem('_tinfo');
				}
			}
		})();
	}

	whileLoop();
})();

// SEE IF COOKIE CONSENT HAS HAPPENED
var cc_cookie = slpGetCookie("CookieConsent");
if (cc_cookie === null){


	// CookieConsent has not happened yet - attempt to capture tinfo to localstorage
		cookieloop(0);
} else {
		// CookieConsent has happened
		if (localStorage.getItem('_tinfo') === null){
				// No tinfo captured - do nothing
		} else {
				// Normalize cookie values
				while (cc_cookie.indexOf('%2C') != -1){
						cc_cookie = cc_cookie.replace('%2C',',');
				}

				// DEFAULT PREFERENCES
				var necessary   = true;
				var preferences = false;
				var statistics  = false;
				var marketing   = false;

				// SPLIT COOKIE VALUES
				var cookiearray = cc_cookie.split(",");

				// SEE WHAT THE USER SELECTED
				cookiearray.forEach(function(item){
						var itm = item.split(":");
						switch (itm[0]){
								case "preferences":
										if (itm[1] == "true"){
												preferences = true;
										}
								break;
								case "statistics":
										if (itm[1] == "true"){
												statistics = true;
										}
								break;
								case "marketing":
										if (itm[1] == "true"){
												marketing = true;
										}
								break;
						}
				});

				// ARE ANY ADDITIONAL VALUES SELECTED AS TRUE?
				if (preferences || statistics || marketing){
						// THEY OPTED IN - CAPTURING TINFO

						var tinfo = localStorage.getItem('_tinfo');
						slpSetCookie("tinfo", tinfo,30);
				}
				localStorage.removeItem('_tinfo');
		}
}

