// GET THE SUBDOMAIN PREFIX
var parts = location.hostname.split('.');
var subdomain = parts.shift();

if (subdomain != "www"){
  // THIS IS A FL VISITOR
  updateNavFts();
}

function updateNavFts(){
	// MAKE SURE JQUERY IS LOADED

  // ENSURE GLOBAL JQUERY IS PRESENT
	if (!window.jQuery){
		return setTimeout(updateNavFts, 100);
	}

  // CAPTURE JQUERY
  jquery = window.jQuery;

  // LINKS AND FTS'S WE ARE INTERESTED IN
  var links = [
    {
      url : "/contact",
      fts : ['nav-contact-why-smartsheet','nav-contact-product','nav-contact-enterprise','nav-contact-resources','nav-contact-mobile','contact-header-nav']
    },
    {
      url : "/contact/watch-demo",
      fts : ['nav-demo-why-smartsheet','nav-demo-product','nav-demo-enterprise','nav-demo-resources','nav-demo-mobile']
    }
  ];

  // LOOP THROUGH EVERY FORM
  jquery("nav.global-nav").find("a").each(function (ai, anchor) {

    if (typeof jquery(this).attr('id') === 'undefined'){
      var curlinkid = "nav_" + ai;
      jquery(this).prop('id', curlinkid);
    } else {
      var curlinkid = jquery(this).attr('id');
    }

    // RUNNING TOGGLE, IN CASE WE FIND LATER WE SHOULD NOT PROCESS
    var processurl = true;

    // CAPTURE CURRENT HREF
    var cururl = jquery(this).attr("href");

    // MAKE RELATIVE, IF NECESSARY
    if (cururl.indexOf('smartsheet.com') != -1){
      // THIS IS A FQDN LINK - IF SO, IT SHOULD BE TO THE CURRENT DOMAIN
      if (cururl.indexOf(subdomain + '.smartsheet.com') != -1){
        // THIS URL WE WILL LOOK AT
        cururl = cururl.split(subdomain + '.smartsheet.com');
        cururl = cururl[1];
      } else {
        processurl = false;
      }
    }

    if (!processurl){
      // URL IS NOT OF INTEREST
    } else {
      jquery.each(links, function( i, link ) {
        var checkfor = link.url + "?";
        if (cururl.substr(0, checkfor.length) == checkfor){

          // BREAK URL INTO PIECES
          var splitparts = cururl.split('?');
          var baseurl = splitparts[0];
          var params = splitparts[1];
          var allparams = {};

          // IF MULTIPLE K/V PAIRS PRESENT
          if (params.trim().indexOf('&') != -1) {
              // SPLIT INTO INDIVIDUAL ITEMS
              jquery(params.trim().split("&")).each(function (el) {
                // SPLIT K/V
                var splitvals = optyNBSplitPair(this);

                // ADD K/V TO LARGER ARRAY
                jquery.each(splitvals, function (key, value) {
                    allparams[key] = value;
                });
              });
          } else {
              // WE HAVE 1 ITEM
              splitvals = optyNBSplitPair(params);

              // ADD K/V TO LARGER ARRAY
              jquery.each(splitvals, function (key, value) {
                  allparams[key] = value;
              });
          }

          // CHECK FOR FTS EXISTENCE
          if (typeof allparams['fts'] !== 'undefined') {
              // GRAB CURRENT FTS VALUE
              var curfts = allparams['fts'];

              var updatefts = false;
              jquery.each(link.fts, function (key, value){
                if (value == curfts){
                  updatefts = true;
                }
              });
            
              if (updatefts){
                // CREATE THE NEW FTS VALUE
                var newfts = subdomain + "-" + curfts.trim();
  
                // UPDATE THE FTS VALUE IN THE ORIGINAL ARRAY
                allparams['fts'] = newfts;
  
                // COMBINE THE ORIGINAL BASE URL WITH THE NEW PARAM STRING
                var paramstringnew = optyNBImplodeArr(allparams);
                var urlnew = baseurl + "?" + paramstringnew;
  
                // SET HREF ON THE LINK
                jquery("#" + curlinkid).prop("href", urlnew);
              } else {
              }
          } else {
              // THERE IS NO FTS VALUE ON THIS FORM
          }
        }
      });
    }
  });
}

function optyNBImplodeArr(arr){
	jquery = window.jQuery;
	var newarr = "";
	jquery.each(arr, function (key, value){
		newarr += "&" + key + "=" + value;
	});
	return newarr.substring(1);
}

function optyNBSplitPair(pair){
	// RETURN OBJECT INITIALIZATION
	var returnpair = {};
  
	// CHECK IF K/V PAIR OR JUST KEY
	if (pair.trim().indexOf("=") != -1){
		// K=V FORMAT - RETURN K=V
		var pieces = pair.trim().split("=");
		returnpair[pieces[0].toString()] = pieces[1].toString();
	} else {
		// K FORMAT - RETURN K=K
		returnpair[pair.toString()] = pair.toString();
	}

	// RETURN SPLIT VALUES
	return returnpair;
}

