function isDGSuppressed(){
	jquery = window.jQuery || window.optimizely.get('jquery');

    // CHECK IF THE CONDITION REQUIRES WE SUPPRESS CONTENT FOR DG
	// CHECK URL PATH
	var path = window.location.pathname;
    var suppress = false;

	if (
		(path.trim().toLowerCase().substring(0,3) == '/s/') || 
		(path.trim().toLowerCase().substring(0,49) == '/content-center/best-practices/project-management') || 
		(path.trim().toLowerCase().substring(0,28) == '/impact-calculator-customers') || 
		(path.trim().toLowerCase().substring(0,8) == '/contact') || 
    (path.trim().toLowerCase().substring(0,7) == '/try-it')
	){
		// WE SUPPRESS
		console.log ("[SUPPRESS DRIFT] suppress for path");
        suppress = true;
	} else {
		// LOOK FOR <meta ga-dim="IC_{SOMETHING}" />
		jquery("meta").each(function(i){
			metatag = jquery(this);
			console.log("[SUPPRESS DRIFT] Meta tag(s) found");
			if (jquery(this).attr('ga-dim')){
				 console.log("[SUPPRESS DRIFT] ga-dim found");
				if (jquery(this).attr('ga-dim').trim().toLowerCase().substring(0,3) == 'ic_'){
					// WE SUPPRESS
					console.log ("[SUPPRESS DRIFT] suppress for ic ga-dim");
					suppress = true;
				}
			}
		});
	}

    return suppress;
}

function optlySuppressDrift(){
	// MAKE SURE JQUERY IS LOADED

	if (!window.jQuery){
		console.log ("[SUPPRESS DRIFT] no jquery, restart");
		return setTimeout(optlySuppressDrift, 100);
	}

	console.log ("[SUPPRESS DRIFT] jquery found");

	// CAPTURE JQUERY OBJECT
	jquery = window.jQuery || window.optimizely.get('jquery');

	// INITIALIZE SUPPRESSION SWITCH
	var suppress = false;
    suppress = isDGSuppressed();

    console.log("SUPPRESS",suppress);

	// DO DRIFT SUPPRESSION
	if (suppress === true){
		console.log ("[SUPPRESS DRIFT] do suppression");
		optlyWaitForElementToDisplay("#drift-widget-container",function(){
			console.log("[SUPPRESS DRIFT] ready - start suppression");
			//jquery("#drift-widget-container").remove();

			console.log("[SUPPRESS DRIFT] drift has been suppressed");
		},500,15000);

	} else {
		console.log("[SUPPRESS DRIFT] not suppressing drift");
	}
}


// RUN DRIFT SUPPRESSION FUNCTION
optlySuppressDrift();

function optlyWaitForElementToDisplay(selector, callback, checkFrequencyInMs, timeoutInMs) {
	console.log("[SUPPRESS DRIFT]","[WAIT] start loop");
	var startTimeInMs = Date.now();
	(function loopSearch() {
		if (document.querySelector(selector) != null) {
			console.log("[SUPPRESS DRIFT]","[WAIT] element found");
			callback();
			return;
		} else {
			console.log("[SUPPRESS DRIFT]","[WAIT] element not found - next loop");
			setTimeout(function () {
				if (timeoutInMs && Date.now() - startTimeInMs > timeoutInMs)
					return;
				loopSearch();
			}, checkFrequencyInMs);
		}
	})();
}

