    logEnabled = editorMode || window.localStorage.getItem('logRecs');

// Customized console.log function that only logs while in the editor
var log = function() {
  if(logEnabled) console.log.apply(console, arguments);
};

// function to render the HTML for the component
function renderHTML() {
  log ("[OPTLY] Render Lenny Component");

  // CREATE LOGO SET
  var logoset = [];
  var logos_field = extension.images;
  if (logos_field.trim() != ""){
    // WE HAVE SOME VALUE FOR THE LOGOS
    logos_field = logos_field.split("\n");
    for(logo in logos_field){
      var curlogo = logos_field[logo];
      if (curlogo.trim() != ""){
        // NO BLANK LINES
        console.log ("[LENNY] LOGO " + logo, curlogo);
        console.log ("[LENNY]", '{"url":"' + curlogo.trim() + '", "id":' + logo + '}');
        logoset.push({"url":curlogo.trim(), "id":logo});
      }
    }
  }

  console.log("[LENNY] logoset", logoset);

  // RENDER THE HTML
  var html = extension.$render({
    extension: extension,
    logos: logoset
  });

  log("the html is: " + html);
  console.log("[LENNY] html", html);

  utils.waitForElement(extension.selector).then(function(selectorElem) {
    log ("[OPTLY] element for placement found");

    // Inject the extension html onto the page.
    switch (extension.placement) {
      case 'before':
        selectorElem.insertAdjacentHTML('beforebegin', html);
        break;
      case 'after':
        selectorElem.insertAdjacentHTML('afterend', html);
        break;
      case 'prepend':
        selectorElem.insertBefore(html, selectorElem.firstChild);
        break;
      case 'append':
        selectorElem.appendChild(html);
        break;
      case 'replace-content':
        selectorElem.innerHTML= html;
        break;
      default:
        throw new Error('Unknown placement ' + extension.placement);
    }
  });
}

// INITIALIZE FIELDS FILLED BOOLEAN
var fieldsfilled = true;

// ENSURE ALL THE FIELDS ARE FILLED BEFORE WE INSERT
for (field in extension){
    // PREDEFINED FIELDS START WITH $ OR _
    if((field.substr(0,1) != "$") && (field.substr(0,1) != "_")){
        if (extension[field].trim() == ""){
            log ("[OPTLY] " + field + " not filled - not inserting");
            fieldsfilled = false;
        }
    }
}
  
if (fieldsfilled) {
  // Wait until the targeted element exists, before attempting to insert the new component
  log ("[OPTLY] all fields filled - inserting component");
  utils.waitForElement(extension.selector).then(renderHTML);
}
