  utils.waitForElement('body').then(function (body) {
    body.insertAdjacentHTML('beforeend', extension.$html);
    var banner = document.getElementById('opty-edge');
    if (!banner) { 
      return; 
    }


    // Load the theme's Edge Banner behavior.
    function attach() {
      if (window.Drupal && typeof Drupal.attachBehaviors === 'function') {
        Drupal.attachBehaviors(document.body);
      }
    }
    if (document.getElementById('opty-edge-js')) {
      attach();
    } else {
      var pothosJs = document.createElement('script');
      pothosJs.id = 'opty-edge-js';
      pothosJs.src = '/themes/custom/valinor/js/component-edge-banner.js';
      pothosJs.onload = attach;
      document.head.appendChild(pothosJs);
    }
    // Fire the banner display event.
    window.optimizely = window.optimizely || [];
    window.optimizely.push({ type: 'event', eventName: 'edge_banner_display' });

    // CTA click events.
    banner.querySelectorAll('.edge-banner__ctas a').forEach(function (a) {
      a.addEventListener('click', function () {
        window.optimizely.push({ type: 'event', eventName: 'edge_banner_cta_click' });
      });
    });

    // Expand / collapse events .
    var wasOpen = banner.classList.contains('is-open');
    new MutationObserver(function () {
      var isOpen = banner.classList.contains('is-open');
      if (isOpen === wasOpen) { return; }
      wasOpen = isOpen;
      window.optimizely.push({ type: 'event', eventName: isOpen ? 'edge_banner_expand' : 'edge_banner_collapse' });
    }).observe(banner, { attributes: true, attributeFilter: ['class'] });

  });
